/* Verified staff bootstrap. Private workspace data stays in this page's memory. */
(()=>{'use strict';
const API=window.ClinimeAPI,E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={user:null,workspace:null,bookings:[],epoch:0,loaded:false,read:false,pending:null,dirty:false,asOf:null,lastRead:0,stale:false},auth={phase:'loading',email:'',challenge:null,request:null,busy:false,error:''};
const categories={skin:'العناية بالبشرة',injectables:'الحقن التجميلي',laser:'الليزر',cosmetic:'خدمات تجميلية',consultations:'الاستشارات'};
function project(workspace){
 const raw=Array.isArray(workspace.catalog)?workspace.catalog:[],services=raw.map((s,id)=>({...s,id,backendId:s.id,name:s.nameAr||s.nameEn||s.id,cat:categories[s.category]||s.category,description:s.descriptionAr||s.description||'',availability:s.active===false?'unavailable':s.availability||'available',variants:(s.options||[]).map(v=>({...v,backendId:v.id,name:v.nameAr||v.nameEn||v.id})),image:typeof (s.imageURL||s.image)==='string'&&/^\/api\/media\//.test(s.imageURL||s.image)?s.imageURL||s.image:s.category==='injectables'?'/admin/staff/assets/injectables.webp':['consultations','laser'].includes(s.category)?'/admin/staff/assets/consultation.webp':'/admin/staff/assets/facial-care.webp'}));
 const bookings=Array.isArray(workspace.bookings)?workspace.bookings:[],appointments=bookings.map(b=>{const visit=workspace.visits?.[b.id]||{},items=b.items||[],base=Number(b.pricing?.total??items.reduce((n,i)=>n+Number(i.price||0),0)),baseDuration=items.reduce((n,i)=>n+Number(i.duration||0),0),additions=(visit.additions||[]).map(s=>({...s,name:s.nameAr||s.name||s.nameEn||'',price:Number(s.price)||0,duration:Number(s.duration)||0})),first=services.find(s=>s.backendId===items[0]?.serviceId);return {id:b.id,version:b.revision,patientId:visit.patientId||b.patientId||b.userId||b.id,name:b.attendee?.name||b.contact?.name||'',professional:b.professional,professionalName:b.professionalNameAr||b.professionalNameEn||(b.professional==='gigi'?'جيجي · موعد سابق':'أي أخصائية متاحة'),email:b.contact?.email||'',contactName:b.contact?.name||'',date:b.date,time:b.time,service:first?.id??0,serviceName:items.map(i=>i.nameAr+(i.optionAr?' · '+i.optionAr:'')).join('، '),items,baseDuration,duration:baseDuration+Number(visit.extensionMinutes||0)+additions.reduce((n,i)=>n+i.duration,0),price:Number(visit.total??base+additions.reduce((n,i)=>n+i.price,0)),paid:Number(visit.paid)||0,status:b.status==='cancelled'?'cancelled':['session','checkout','closed'].includes(visit.stage)?visit.stage:b.attendance?.status==='arrived'?'waiting':'expected',arrival:b.attendance?.arrivedAt?new Date(b.attendance.arrivedAt).toLocaleTimeString('ar-SA',{timeZone:'Asia/Riyadh',hour:'2-digit',minute:'2-digit'}):null,startedAt:visit.startedAt?new Date(visit.startedAt).getTime():null,review:!(workspace.medical?.[visit.patientId]?.flags?.consultation&&workspace.medical?.[visit.patientId]?.flags?.assessment&&workspace.medical?.[visit.patientId]?.flags?.consent),decisionRequested:visit.decision?.value==='hold',doctorDecision:visit.decision?.value||'',note:visit.notes||'',sessionNotes:visit.sessionNotes||'',aftercare:visit.aftercare||'',followup:visit.followup||false,additions,history:visit.history||[],attendance:visit.attendanceResponse?.answer||'',emailStatus:b.emailStatus,raw:b};});
 const medical={};for(const [id,record]of Object.entries(workspace.medical||{}))medical[id]={...(record.fields||{}),consultation:!!record.flags?.consultation,assessment:!!record.flags?.assessment,consent:!!record.flags?.consent};
 const stock=Object.values(workspace.stock||{}).map(s=>({...s,qty:s.quantity??s.qty??0,min:s.min||0,expiry:s.expiry||'',sku:s.sku||'',type:s.type||'مواد استهلاكية',kind:s.kind||'مستهلك',condition:s.condition||'متاح',version:s.version??workspace.revision,variants:(s.variants||[]).map(v=>({...v,qty:v.quantity??v.qty??0}))}));
 const receipts=(workspace.receipts||[]).map(r=>({...r,appointment:r.bookingId,number:r.number||r.id,name:appointments.find(a=>a.id===r.bookingId)?.name||'',service:(r.lines||[]).map(i=>i.nameAr||i.name).join('، '),items:r.lines||[],total:r.total??r.amount,previous:r.previous??0,amount:r.amount,date:new Date(r.recordedAt).toLocaleDateString('ar-SA'),time:new Date(r.recordedAt).toLocaleTimeString('ar-SA')}));
 return {services,db:{appointments,receipts,medical,stock,products:Object.values(workspace.products||{}).map(p=>({...p,stockId:p.stockId||''})),stockLog:(workspace.stockLog||[]).map(h=>({...h,before:h.quantityBeforeVerified===false?'غير موثق':h.quantityBefore,after:h.quantityAfterVerified===false?'غير موثق':h.quantityAfter,actor:'سجل الخادم',sku:h.itemId})),messages:{},inventoryRevision:workspace.revision,catalogRevision:workspace.revision}};
}
function login(){document.querySelectorAll('.sidebar,.workspace,#chatLauncher,#chatPanel').forEach(el=>el.hidden=true);let el=document.getElementById('staff-auth');if(!el){el=document.createElement('main');el.id='staff-auth';el.className='staff-auth';document.body.append(el);}const code=auth.phase==='code';el.innerHTML=`<section class="panel padded"><img class="brand" src="/admin/staff/assets/clinime.svg" alt="Clinime"><h1>مكتب الاستقبال</h1><p>${auth.phase==='loading'?'جارٍ التحقق من الدخول':auth.phase==='denied'?'هذا الحساب غير مخوّل للوصول إلى بيانات العيادة.':'تسجيل الدخول لإدارة كلينيمي'}</p>${auth.phase==='loading'?'':auth.phase==='denied'?'<button class="primary" data-auth="logout">الخروج من الحساب</button>':`<form data-auth-form="${code?'verify':'request'}"><label>البريد الإلكتروني<input name="email" type="email" autocomplete="email" dir="ltr" required value="${E(auth.email)}" ${code?'readonly':''}></label>${code?'<label>رمز الدخول<input name="code" dir="ltr" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9٠-٩]{6}" maxlength="6" required></label>':''}<button class="primary" ${auth.busy?'disabled':''}>${auth.busy?'جارٍ المتابعة':code?'دخول':'إرسال رمز الدخول'}</button></form>${code?'<button data-auth="change">تعديل البريد</button>':''}`}<p role="alert">${E(auth.error)}</p><a href="/">موقع الحجز</a></section>`;}
function clear(phase='email'){state.epoch++;state.read=false;state.user=null;state.workspace=null;state.bookings=[];state.pending=null;state.dirty=false;API.setCSRF('');if(window.StaffBridge)window.StaffBridge.clear();delete window.StaffInitial;auth.phase=phase;auth.error='';document.querySelector('#dialog')?.close();login();}
async function loadScripts(){if(state.loaded)return;state.loaded=true;for(const name of ['handler-parser.js','app.js','team.js','bridge.js','loyalty.js','marketing.js','care-point.js','dashboard.js','reviews.js',...(['127.0.0.1','localhost','[::1]'].includes(location.hostname)?['growth-data.js','growth.js']:[])])await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='/admin/staff/'+name;s.onload=resolve;s.onerror=()=>reject(new Error('تعذّر تحميل واجهة الفريق'));document.head.append(s);});}
async function refresh({session=false,manual=false}={}){if(state.read||state.pending||!session&&(!state.user||document.hidden||state.dirty||document.querySelector('#dialog')?.open||!manual&&document.querySelector('#main form')))return false;state.read=true;const epoch=state.epoch,route=location.hash;try{if(session){const me=await API.request('/api/admin/me');if(epoch!==state.epoch)return false;state.user=me.user;API.setCSRF(me.csrfToken);}const workspace=await API.request('/api/admin/workspace');if(epoch!==state.epoch||state.pending||!session&&(state.dirty||document.querySelector('#dialog')?.open||route!==location.hash||!manual&&document.querySelector('#main form')))return false;state.workspace=workspace;state.bookings=workspace.bookings||[];state.asOf=workspace.asOf;state.lastRead=Date.now();state.stale=false;const initial=project(workspace);if(!state.loaded){window.StaffInitial=initial;await loadScripts();}else window.StaffBridge.apply(initial);document.getElementById('staff-auth')?.remove();document.querySelectorAll('.sidebar,.workspace').forEach(el=>el.hidden=false);window.StaffBridge.render();return true;}catch(error){if(epoch!==state.epoch)return false;if([401,403].includes(error.status)){clear(error.status===403?'denied':'email');return false;}if(!state.loaded||!window.StaffBridge){auth.phase='email';auth.error=error.message||'تعذّر الاتصال بالخدمة';login();}else{state.stale=true;window.StaffBridge.feedback(error.message||'تعذّر تحديث البيانات');}return false;}finally{if(epoch===state.epoch)state.read=false;}}
async function logout(){if(state.pending?.phase==='sending')return;state.epoch++;state.read=false;try{if(!state.user){const me=await API.me();if(!me.user){clear();return;}API.setCSRF(me.csrfToken);}await API.logout();clear();}catch(error){if(error.status===401)clear();else if(state.loaded)window.StaffBridge.feedback('تعذّر تسجيل الخروج. أعيدي المحاولة.');else{auth.error=error.message;login();}}}
window.StaffRuntime={state,API,project,refresh,clear,logout,E};
document.addEventListener('submit',async e=>{const form=e.target.closest('[data-auth-form]');if(!form)return;e.preventDefault();if(auth.busy)return;const f=new FormData(form);auth.busy=true;auth.error='';try{if(form.dataset.authForm==='request'){auth.email=String(f.get('email')||'').trim().toLowerCase();if(!auth.request||auth.request.email!==auth.email)auth.request={requestId:API.uuid(),email:auth.email,locale:'ar',mode:'code'};auth.challenge=await API.authRequest(auth.request);auth.request=null;auth.phase='code';}else{const code=String(f.get('code')||'').replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c));const result=await API.verify({challengeId:auth.challenge.challengeId,code});API.setCSRF(result.csrfToken);auth.challenge=null;state.epoch++;state.read=false;await refresh({session:true});}}catch(error){auth.error=error.message;if(!error.uncertain)auth.request=null;}finally{auth.busy=false;if(!state.workspace)login();}});
document.addEventListener('click',e=>{const a=e.target.closest('[data-auth]')?.dataset.auth;if(a==='logout')logout();if(a==='change'){auth.phase='email';auth.challenge=null;auth.request=null;login();}});
setInterval(()=>refresh(),60000);window.addEventListener('focus',()=>{if(Date.now()-state.lastRead>30000)refresh();});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&Date.now()-state.lastRead>30000)refresh();});
login();refresh({session:true});
})();
